import React, { useState, useEffect, useRef } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import "./Navbar.css";

const Navbar = ({ refreshAuthState }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isUserDropdownOpen, setIsUserDropdownOpen] = useState(false);
  const [theme, setTheme] = useState('light');
  const navigate = useNavigate();
  const location = useLocation();
  const dropdownRef = useRef(null);
  const menuRef = useRef(null);

  const isLoggedIn = !!localStorage.getItem('token');

  // Theme management
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    
    if (savedTheme) {
      setTheme(savedTheme);
      applyTheme(savedTheme);
    } else if (prefersDark) {
      setTheme('dark');
      applyTheme('dark');
    }
  }, []);

  const applyTheme = (newTheme) => {
    document.documentElement.setAttribute('data-theme', newTheme);
    document.body.setAttribute('data-theme', newTheme);
  };

  const toggleTheme = () => {
    const newTheme = theme === 'light' ? 'dark' : 'light';
    setTheme(newTheme);
    localStorage.setItem('theme', newTheme);
    applyTheme(newTheme);
  };

  // Handle logout
  const handleLogout = () => {
    localStorage.removeItem('token');
    if (refreshAuthState) {
      refreshAuthState();
    }
    setIsUserDropdownOpen(false);
    setIsMenuOpen(false);
    navigate('/login');
  };

  // Close dropdowns when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsUserDropdownOpen(false);
      }
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setIsMenuOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  // Close mobile menu on route change
  useEffect(() => {
    setIsMenuOpen(false);
    setIsUserDropdownOpen(false);
  }, [location.pathname]);

  // Handle keyboard navigation
  const handleKeyDown = (event, action) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      action();
    }
    if (event.key === 'Escape') {
      setIsMenuOpen(false);
      setIsUserDropdownOpen(false);
    }
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        {/* Brand */}
        <Link to="/" className="navbar-brand">
          <i className="fas fa-sticky-note navbar-brand-icon"></i>
          <span>Diary Desk</span>
        </Link>

        {/* Desktop Navigation */}
        <div className={`navbar-menu ${isMenuOpen ? 'show' : ''}`} ref={menuRef}>
          {isLoggedIn && (
            <ul className="navbar-nav">
              <li>
                <Link
                  to="/"
                  className={`nav-link ${location.pathname === "/" ? "active" : ""}`}
                >
                  <i className="fas fa-home"></i>
                  <span>Home</span>
                </Link>
              </li>
              <li>
                <Link
                  to="/about"
                  className={`nav-link ${location.pathname === "/about" ? "active" : ""}`}
                >
                  <i className="fas fa-info-circle"></i>
                  <span>About</span>
                </Link>
              </li>
            </ul>
          )}

          <div className="navbar-actions">
            {/* Theme Toggle */}
            <button
              className="theme-toggle"
              onClick={toggleTheme}
              onKeyDown={(e) => handleKeyDown(e, toggleTheme)}
              title={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`}
              aria-label={`Switch to ${theme === 'light' ? 'dark' : 'light'} mode`}
            >
              <i className={`fas ${theme === 'light' ? 'fa-moon' : 'fa-sun'}`}></i>
              <span>{theme === 'light' ? 'Dark' : 'Light'}</span>
            </button>

            {/* Authentication Buttons or User Dropdown */}
            {!isLoggedIn ? (
              <div className="auth-buttons">
                <Link to="/login" className="btn btn-outline-primary">
                  <i className="fas fa-sign-in-alt"></i>
                  <span>Login</span>
                </Link>
                <Link to="/signup" className="btn btn-primary">
                  <i className="fas fa-user-plus"></i>
                  <span>Signup</span>
                </Link>
              </div>
            ) : (
              <div className="user-dropdown" ref={dropdownRef}>
                <button
                  className="user-dropdown-toggle"
                  onClick={() => setIsUserDropdownOpen(!isUserDropdownOpen)}
                  onKeyDown={(e) => handleKeyDown(e, () => setIsUserDropdownOpen(!isUserDropdownOpen))}
                  aria-expanded={isUserDropdownOpen}
                  aria-haspopup="true"
                >
                  <i className="fas fa-user-circle"></i>
                  <span>Account</span>
                  <i className={`fas fa-chevron-${isUserDropdownOpen ? 'up' : 'down'}`}></i>
                </button>
                
                <div className={`user-dropdown-menu ${isUserDropdownOpen ? 'show' : ''}`}>
                  <Link
                    to="/profile"
                    className="dropdown-item"
                    onClick={() => setIsUserDropdownOpen(false)}
                  >
                    <i className="fas fa-user-cog"></i>
                    <span>Profile</span>
                  </Link>
                  <Link
                    to="/"
                    className="dropdown-item"
                    onClick={() => setIsUserDropdownOpen(false)}
                  >
                    <i className="fas fa-sticky-note"></i>
                    <span>My Notes</span>
                  </Link>
                  <div className="dropdown-divider"></div>
                  <button
                    className="dropdown-item"
                    onClick={handleLogout}
                    onKeyDown={(e) => handleKeyDown(e, handleLogout)}
                  >
                    <i className="fas fa-sign-out-alt"></i>
                    <span>Logout</span>
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Mobile Menu Toggle */}
        <button
          className="navbar-toggle"
          onClick={() => setIsMenuOpen(!isMenuOpen)}
          onKeyDown={(e) => handleKeyDown(e, () => setIsMenuOpen(!isMenuOpen))}
          aria-expanded={isMenuOpen}
          aria-label="Toggle navigation menu"
        >
          <i className={`fas ${isMenuOpen ? 'fa-times' : 'fa-bars'}`}></i>
        </button>
      </div>
    </nav>
  );
};

export default Navbar;
